def _vigentes(Historial, inmueble_id, modalidad_id, hoy):
    return list(
        Historial.objects.filter(inmueble_id=inmueble_id, modalidad_id=modalidad_id, fecha__lte=hoy)
        .order_by('-fecha')
    )


def historial_y_ultima_renta(apps, schema_editor):
    """Make the latest history row equal each current price, then keep `ultima_renta` as the row before it."""
    Oferta = apps.get_model('base', 'InmuebleModalidad')
    Historial = apps.get_model('base', 'HistorialPrecio')
    hoy = datetime.date.today()
    for oferta in Oferta.objects.select_related('inmueble', 'modalidad'):
        filas = _vigentes(Historial, oferta.inmueble_id, oferta.modalidad_id, hoy)
        if not filas or filas[0].importe != oferta.precio:
            Historial.objects.update_or_create(
                inmueble_id=oferta.inmueble_id, modalidad_id=oferta.modalidad_id, fecha=hoy,
                defaults={'importe': oferta.precio},
            )
            filas = _vigentes(Historial, oferta.inmueble_id, oferta.modalidad_id, hoy)
        ultima = oferta.inmueble.ultima_renta
        if ultima is not None and oferta.modalidad.unidad_precio == 'mensual' and len(filas) == 1:
            Historial.objects.get_or_create(
                inmueble_id=oferta.inmueble_id, modalidad_id=oferta.modalidad_id,
                fecha=filas[0].fecha - datetime.timedelta(days=1),
                defaults={'importe': ultima, 'nota': 'Última renta (migrada)'},
            )


def ultima_renta_al_inmueble(apps, schema_editor):
    """Back to one figure per listing: the previous price of its first monthly offer."""
    Oferta = apps.get_model('base', 'InmuebleModalidad')
    Historial = apps.get_model('base', 'HistorialPrecio')
    Inmueble = apps.get_model('base', 'Inmueble')
    hoy = datetime.date.today()
    hechos = set()
    for oferta in Oferta.objects.filter(modalidad__unidad_precio='mensual').select_related('modalidad').order_by(
        'modalidad__orden', 'modalidad__codigo'
    ):
        if oferta.inmueble_id in hechos:
            continue
        filas = _vigentes(Historial, oferta.inmueble_id, oferta.modalidad_id, hoy)
        if len(filas) > 1:
            Inmueble.objects.filter(pk=oferta.inmueble_id).update(ultima_renta=filas[1].importe)
            hechos.add(oferta.inmueble_id)


